 *
 * <p>The job runs automatically on startup ({@code spring.batch.job.enabled=true})
 * and the application exits when the job completes (standard batch lifecycle).
 */
@SpringBootApplication
public class Cbact02cApplication {

    public static void main(String[] args) {
        SpringApplication.run(Cbact02cApplication.class, args);
    }
}

package com.carddemo.cbact02c.batch;

import com.carddemo.cbact02c.domain.CardRecord;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.stereotype.Component;

/**
 * Formats a {@link CardRecord} as a fixed-width display string.
 *
 * <p>Mirrors the COBOL {@code DISPLAY CARD-RECORD} statement in CBACT02C.cbl.
 * In COBOL, {@code DISPLAY} writes the raw bytes of the record group to SYSOUT,
 * concatenating all sub-fields in declaration order.  This processor reproduces
 * that layout so the batch writer can log or write an equivalent line.
 *
 * <p>COBOL source reference: CBACT02C.cbl — main PERFORM loop:
 * <pre>
 * PERFORM UNTIL END-OF-FILE = 'Y'
 *     IF END-OF-FILE = 'N'
 *         PERFORM 1000-CARDFILE-GET-NEXT
 *         IF END-OF-FILE = 'N'
 *             DISPLAY CARD-RECORD        ← this processor
 *         END-IF
 *     END-IF
 * END-PERFORM.
 * </pre>
 *
 * <p>Record layout (CVACT02Y.cpy, total 150 bytes):
 * <pre>
 * Pos  0-15  : CARD-NUM            PIC X(16)
 * Pos 16-26  : CARD-ACCT-ID        PIC 9(11)
 * Pos 27-29  : CARD-CVV-CD         PIC 9(03)
 * Pos 30-79  : CARD-EMBOSSED-NAME  PIC X(50)
 * Pos 80-89  : CARD-EXPIRAION-DATE PIC X(10)
 * Pos 90     : CARD-ACTIVE-STATUS  PIC X(01)
 * Pos 91-149 : FILLER              PIC X(59)
 * </pre>
 */
@Component
public class CardDisplayProcessor implements ItemProcessor<CardRecord, String> {

    /**
     * Converts a {@link CardRecord} entity to its COBOL DISPLAY representation.
     *
     * <p>Numeric sub-fields (CARD-ACCT-ID, CARD-CVV-CD) are zero-padded to their
     * declared PIC widths, exactly as COBOL stores them in the record buffer.
     * Alphanumeric sub-fields are left-justified and space-padded to their declared widths.
     *
     * @param card the card record read from the database
     * @return the 150-character display line (matching COBOL DISPLAY CARD-RECORD output)
     */
    @Override
    public String process(CardRecord card) {
        // COBOL: DISPLAY CARD-RECORD — outputs all sub-fields concatenated
        return String.format("%-16s%011d%03d%-50s%-10s%-1s%-59s",
                nullToEmpty(card.getCardNum()),
                card.getCardAcctId(),
                parseCvv(card.getCardCvvCd()),
                nullToEmpty(card.getCardEmbossedName()),
                nullToEmpty(card.getExpirationDate()),
                nullToEmpty(card.getActiveStatus()),
                "");  // FILLER PIC X(59) — always spaces
    }

    private String nullToEmpty(String s) {
        return s == null ? "" : s;
    }

    private int parseCvv(String cvv) {
        if (cvv == null || cvv.isBlank()) return 0;
        try {
            return Integer.parseInt(cvv.strip());
        } catch (NumberFormatException e) {
            return 0;
        }
    }
}

package com.carddemo.cbact02c.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * JPA entity representing one card data record.
 *
 * <p>Maps the COBOL copybook {@code CVACT02Y.cpy} (CARD-RECORD, 150 bytes):
 * <pre>
 * 01  CARD-RECORD.
 *     05  CARD-NUM               PIC X(16)    → card_num       CHAR(16)   PK
 *     05  CARD-ACCT-ID           PIC 9(11)    → card_acct_id   BIGINT
 *     05  CARD-CVV-CD            PIC 9(03)    → card_cvv_cd    CHAR(3)    (sensitive)
 *     05  CARD-EMBOSSED-NAME     PIC X(50)    → card_embossed_name VARCHAR(50)
 *     05  CARD-EXPIRAION-DATE    PIC X(10)    → expiration_date CHAR(10)  (typo from source)
 *     05  CARD-ACTIVE-STATUS     PIC X(01)    → active_status  CHAR(1)
 *     05  FILLER                 PIC X(59)    → not stored
 * </pre>
 *
 * <p>COBOL FD: CBACT02C.cbl:37-40 — FD CARDFILE-FILE / 01 FD-CARDFILE-REC.
 * COBOL SELECT: CBACT02C.cbl:28-33 — ORGANIZATION IS INDEXED, RECORD KEY IS FD-CARD-NUM.
 */
@Entity
@Table(name = "card_records")
public class CardRecord {

    /** COBOL: CARD-NUM PIC X(16) — primary KSDS record key. */
    @Id
    @Column(name = "card_num", length = 16, nullable = false)
    private String cardNum;

    /** COBOL: CARD-ACCT-ID PIC 9(11) — associated account identifier. */
    @Column(name = "card_acct_id", nullable = false)
    private Long cardAcctId;

    /**
     * COBOL: CARD-CVV-CD PIC 9(03) — card verification value.
     * Stored as CHAR(3) to preserve leading zeros (e.g. "007").
     * NOTE: in a production system this field should not be persisted.
     */
    @Column(name = "card_cvv_cd", length = 3, nullable = false)
    private String cardCvvCd;

    /** COBOL: CARD-EMBOSSED-NAME PIC X(50) — name printed on the card face. */
    @Column(name = "card_embossed_name", length = 50, nullable = false)
    private String cardEmbossedName;

    /**
     * COBOL: CARD-EXPIRAION-DATE PIC X(10) — card expiry date.
     * Field name preserves the original COBOL typo ("EXPIRAION") from CVACT02Y.
     */
    @Column(name = "expiration_date", length = 10)
    private String expirationDate;

    /** COBOL: CARD-ACTIVE-STATUS PIC X(01) — 'Y' = active, 'N' = inactive. */
    @Column(name = "active_status", length = 1, nullable = false)
    private String activeStatus;

    // ── Constructors ──────────────────────────────────────────────────────

    protected CardRecord() {}

    public CardRecord(String cardNum, Long cardAcctId, String cardCvvCd,
                      String cardEmbossedName, String expirationDate, String activeStatus) {
        this.cardNum = cardNum;
        this.cardAcctId = cardAcctId;
        this.cardCvvCd = cardCvvCd;
        this.cardEmbossedName = cardEmbossedName;
        this.expirationDate = expirationDate;
        this.activeStatus = activeStatus;
    }

    // ── Accessors ─────────────────────────────────────────────────────────

    public String getCardNum()          { return cardNum; }
    public Long   getCardAcctId()       { return cardAcctId; }
    public String getCardCvvCd()        { return cardCvvCd; }
    public String getCardEmbossedName() { return cardEmbossedName; }
    public String getExpirationDate()   { return expirationDate; }
    public String getActiveStatus()     { return activeStatus; }
}

